@push('scripts')@include('partials.import-poll')<script>document.addEventListener('click',function(e){var b=e.target.closest('.delete-employee-btn');if(b){document.getElementById('delete_employee_form').action=b.dataset.url;document.getElementById('delete_employee_message').textContent='Are you sure you want to delete "'+b.dataset.name+'"?';}});function applyEmployeeFilter(status){fetch('{{ url('employee-structure/employees/filter') }}',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'},body:JSON.stringify({status:status})}).then(function(r){return r.json();}).then(function(data){var table=document.querySelector('table.datatable');var sourceBody=table.querySelector('tbody');var rowContainer=document.createElement('tbody');rowContainer.innerHTML=data.html;sourceBody.innerHTML=data.html;var visibleBody=document.querySelector('.gridjs-tbody');if(visibleBody){visibleBody.innerHTML='';rowContainer.querySelectorAll('tr').forEach(function(row){row.classList.add('gridjs-tr');row.querySelectorAll('td').forEach(function(cell){cell.classList.add('gridjs-td');});visibleBody.appendChild(row);});}var summary=document.querySelector('.gridjs-summary');if(summary){summary.textContent=data.count===0?'No records to show':'Showing 1-'+data.count+' of '+data.count+' entries';}var pages=document.querySelector('.gridjs-pages');if(pages){pages.innerHTML='';}}).catch(function(error){console.error('Filter error:',error);});}document.querySelectorAll('.employee-status-filter').forEach(function(b){b.addEventListener('click',function(){applyEmployeeFilter(this.dataset.status);});});</script>@endpush
